''','''	Put(ctx context.Context, location *Location) error
	ListRideHistory(ctx context.Context) (*RideHistoryList, error)
	CreateRideHistory(ctx context.Context, ride *RideHistory) (*RideHistory, error)
	UpdateRideHistory(ctx context.Context, ride *RideHistory) error
''')
