s=s.replace('''var seed = ''','''const rideHistoryTableSchema = `
CREATE TABLE IF NOT EXISTS ride_history
(
    id bigint unsigned NOT NULL AUTO_INCREMENT,
    pickup_location varchar(255) NOT NULL,
    dropoff_location varchar(255) NOT NULL,
    request_time datetime(3) NOT NULL,
    driver_plate varchar(64) NOT NULL DEFAULT '',
    fare decimal(10,2) NOT NULL DEFAULT 0,

    PRIMARY KEY (id),
    KEY request_time (request_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
`

// rideHistoryLimit is the max number of rides returned when listing.
const rideHistoryLimit = 50

