// isMissingTable reports whether err is a MySQL "Table doesn't exist" error.
func isMissingTable(err error) bool {
	mysqlErr, ok := err.(*mysql.MySQLError)
	return ok && mysqlErr.Number == 1146
}

// execRideHistory runs a ride_history statement, creating the table and
// retrying once if it doesn't exist.
func (d *database) execRideHistory(query string, args ...interface{}) (sql.Result, error) {
	res, err := d.db.Exec(query, args...)
	if err != nil && isMissingTable(err) {
		if _, err := d.db.Exec(rideHistoryTableSchema); err != nil {
			return nil, err
		}
		res, err = d.db.Exec(query, args...)
	}
	return res, err
}

func (d *database) ListRideHistory(ctx context.Context) (*RideHistoryList, error) {
	d.logger.For(ctx).Info("Loading ride history")

	_, span := d.tracer.Start(ctx, "SQL SELECT", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		semconv.PeerServiceKey.String("mysql"),
		attribute.Key("sql.query").String("SELECT FROM ride_history"),
	)
	defer span.End()

	list := &RideHistoryList{Rides: []RideHistory{}}
	countQuery := "SELECT COUNT(*) FROM ride_history"
	listQuery := "SELECT id, pickup_location, dropoff_location, request_time, driver_plate, fare " +
		"FROM ride_history ORDER BY request_time DESC, id DESC LIMIT ?"

	err := d.db.QueryRowContext(ctx, countQuery).Scan(&list.Total)
	if err != nil && isMissingTable(err) {
		if _, err = d.db.ExecContext(ctx, rideHistoryTableSchema); err == nil {
			err = d.db.QueryRowContext(ctx, countQuery).Scan(&list.Total)
		}
	}
	if err != nil {
		return nil, err
	}

	rows, err := d.db.QueryContext(ctx, listQuery, rideHistoryLimit)
	if err != nil {
		return nil, err
