  "private": true,
  "version": "0.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc && vite build",
    "lint": "eslint . --ext ts,tsx --report-unused-disable-directives --max-warnings 0",
    "preview": "vite preview"
  },
  "dependencies": {
    "@chakra-ui/react": "^2.8.2",
    "@emotion/react": "^11.11.4",
    "@emotion/styled": "^11.11.0",
    "@faker-js/faker": "^9.3.0",
    "framer-motion": "^11.0.8",
    "geojson-path-finder": "^2.0.2",
    "leaflet": "^1.9.4",
    "leaflet-routing-machine": "^3.2.12",
    "pigeon-maps": "^0.21.4",
    "react": "^18.2.0",
    "react-countdown": "^2.3.6",
    "react-dom": "^18.2.0",
    "react-leaflet": "^4.2.1"
  },
  "devDependencies": {
    "@types/leaflet": "^1.9.15",
    "@types/leaflet-routing-machine": "^3.2.8",
    "@types/react": "^18.2.56",
    "@types/react-dom": "^18.2.19",
    "@typescript-eslint/eslint-plugin": "^7.0.2",
    "@typescript-eslint/parser": "^7.0.2",
    "@vitejs/plugin-react": "^4.2.1",
    "eslint": "^8.56.0",
    "eslint-plugin-react-hooks": "^4.6.0",
    "eslint-plugin-react-refresh": "^0.4.5",
    "typescript": "^5.2.2",
    "vite": "^5.1.4"
  }
}
import {
    Accordion,
    AccordionButton,
    AccordionIcon,
    AccordionItem,
    AccordionPanel,
    Box,
    Highlight, HStack, Stack, Text,
} from "@chakra-ui/react";
import {Log} from "../../../hooks/useLogs.tsx";
import {useMemo} from "react";

const getTime = (dt: Date) => {
    return  String(dt.getHours()).padStart(2, '0') + ":" +
        String(dt.getMinutes()).padStart(2, '0') + ":" +
        String(dt.getSeconds()).padStart(2, '0') + "." +
        String(dt.getMilliseconds()).padStart(3, '0');
}


type LocationHighlightProps = {
    type: 'pickup' | 'dropoff',
    value: string
}

const LocationHighlight = ({ type, value }: LocationHighlightProps) => {
    return (
        <Highlight
            query={value}
            styles={{
                px: '1',
                py: '1',
                bg: type === 'pickup' ? 'orange.100' : 'teal.100',
                mx: '2'
        }}>
            {value}
        </Highlight>
    )
}

