  const errs = []; page.on('console', m => { if (m.type()==='error') errs.push(m.text()); });
  const sels = page.locator('select');
  await sels.nth(0).selectOption({ label: 'Rachel\'s Floral Designs' });
  await sels.nth(1).selectOption({ label: 'Japanese Desserts' });
  await page.getByRole('button', { name: 'Request Ride' }).click();
  await page.waitForTimeout(12000);
  const body = await page.innerText('body');
  return { errs, body: body.slice(body.indexOf('The driver') >= 0 ? body.indexOf('The driver') : 0, 1200) };
}

