async (page) => {
  const out = {};
  for (const [name, hdr] of [['sandbox', true], ['baseline', false]]) {
    const ctx = await page.context().browser().newContext(hdr ? { extraHTTPHeaders: { baggage: 'sd-routing-key=0ptjnhnmb8xf0' } } : {});
    const p = await ctx.newPage();
    await p.goto('http://frontend.ctbench-hotrod.svc:8080/');
    await p.waitForLoadState();
    await p.getByRole('combobox').first().selectOption('1');
    await p.getByRole('combobox').nth(1).selectOption('123');
    await p.getByRole('button', { name: 'Request Ride' }).click();
    await p.waitForTimeout(10000);
    const r = {};
    r.route = await p.locator("//div[p[2][contains(text(), 'route')]]/p[4]").first().textContent({timeout:3000}).catch(e=>'ERR');
    r.driver = await p.locator("//div[p[2][contains(text(), 'driver')]]/p[4]").last().textContent({timeout:3000}).catch(e=>'ERR');
    r.cypress = await p.locator(':nth-child(6) > .css-bjcoli').first().textContent({timeout:3000}).then(t=>t.slice(0,80)).catch(e=>'ERR no match');
    r.cyHasDriver = await p.locator(':nth-child(6) > .css-bjcoli').filter({hasText: /Driver (.*) arriving in (.*)./}).count();
    r.ride = (await p.innerText('body')).match(/The driver[^\n]*/)?.[0];
    out[name] = r;
    await ctx.close();
  }
  return out;
}

